import React, { useState, useEffect } from 'react';
import { 
  Clock, 
  ExternalLink, 
  Image as ImageIcon, 
  Loader2, 
  RefreshCw,
  AlertCircle 
} from 'lucide-react';
import { formatDistanceToNow } from 'date-fns';
import { zhCN } from 'date-fns/locale';

const NewsList = ({ category, refreshTrigger }) => {
  const [news, setNews] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [lastUpdate, setLastUpdate] = useState(null);

  const fetchNews = async (pageNum = 1, isRefresh = false) => {
    try {
      setLoading(true);
      setError(null);

      const params = new URLSearchParams({
        page: pageNum.toString(),
        limit: '10'
      });

      if (category !== '全部') {
        params.append('category', category);
      }

      const response = await fetch(`/api/news/latest?${params}`);
      const data = await response.json();

      if (data.success) {
        if (isRefresh || pageNum === 1) {
          setNews(data.data.data);
        } else {
          setNews(prev => [...prev, ...data.data.data]);
        }
        setHasMore(data.data.data.length === 10);
        setLastUpdate(new Date());
      } else {
        throw new Error(data.error || '获取新闻失败');
      }
    } catch (err) {
      console.error('获取新闻失败:', err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  // 初始加载和分类/刷新触发
  useEffect(() => {
    setPage(1);
    fetchNews(1, true);
  }, [category, refreshTrigger]);

  const loadMore = () => {
    if (!loading && hasMore) {
      const nextPage = page + 1;
      setPage(nextPage);
      fetchNews(nextPage);
    }
  };

  const getCategoryColor = (category) => {
    const colors = {
      'AI新闻': 'bg-blue-100 text-blue-700',
      'AI框架': 'bg-green-100 text-green-700',
      '新算法': 'bg-purple-100 text-purple-700',
      '新思路': 'bg-yellow-100 text-yellow-700',
      '新工具': 'bg-pink-100 text-pink-700',
      '全部': 'bg-gray-100 text-gray-700'
    };
    return colors[category] || 'bg-gray-100 text-gray-700';
  };

  if (loading && news.length === 0) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="w-8 h-8 animate-spin text-blue-600 mr-2" />
        <span className="text-gray-600">加载AI资讯中...</span>
      </div>
    );
  }

  if (error && news.length === 0) {
    return (
      <div className="text-center py-12">
        <AlertCircle className="w-12 h-12 text-red-500 mx-auto mb-4" />
        <h3 className="text-lg font-medium text-gray-900 mb-2">加载失败</h3>
        <p className="text-gray-600 mb-4">{error}</p>
        <button
          onClick={() => fetchNews(1, true)}
          className="inline-flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
        >
          <RefreshCw className="w-4 h-4 mr-2" />
          重试
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* 页面头部 */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">
            {category === '全部' ? '最新AI资讯' : `${category}资讯`}
          </h2>
          {lastUpdate && (
            <p className="text-sm text-gray-500 mt-1">
              最后更新: {formatDistanceToNow(lastUpdate, { addSuffix: true, locale: zhCN })}
            </p>
          )}
        </div>

        <div className="flex items-center space-x-2">
          <span className={`px-3 py-1 rounded-full text-xs font-medium ${getCategoryColor(category)}`}>
            {category}
          </span>
          <span className="text-sm text-gray-500">
            共 {news.length} 条
          </span>
        </div>
      </div>

      {/* 新闻列表 */}
      <div className="grid gap-6">
        {news.map((item) => (
          <article
            key={item.id}
            className="bg-white rounded-lg shadow-sm border border-gray-200 p-6 hover:shadow-md transition-shadow"
          >
            <div className="flex items-start space-x-4">
              {/* 图片 */}
              {item.imageUrl && (
                <div className="flex-shrink-0">
                  <img
                    src={item.imageUrl}
                    alt=""
                    className="w-24 h-24 object-cover rounded-lg"
                    onError={(e) => {
                      e.target.style.display = 'none';
                    }}
                  />
                </div>
              )}

              <div className="flex-1 min-w-0">
                {/* 标题和链接 */}
                <h3 className="text-lg font-semibold text-gray-900 mb-2 line-clamp-2">
                  <a
                    href={item.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="hover:text-blue-600 transition-colors"
                  >
                    {item.title}
                  </a>
                </h3>

                {/* 描述 */}
                {item.description && (
                  <p className="text-gray-600 mb-3 line-clamp-3">
                    {item.description}
                  </p>
                )}

                {/* 元信息 */}
                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-4 text-sm text-gray-500">
                    <div className="flex items-center">
                      <Clock className="w-4 h-4 mr-1" />
                      {formatDistanceToNow(new Date(item.publishedAt), { 
                        addSuffix: true, 
                        locale: zhCN 
                      })}
                    </div>

                    <span className="flex items-center">
                      {item.source}
                    </span>

                    <span className={`px-2 py-1 rounded-full text-xs font-medium ${getCategoryColor(item.category)}`}>
                      {item.category}
                    </span>
                  </div>

                  <a
                    href={item.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex items-center text-blue-600 hover:text-blue-700 transition-colors"
                  >
                    <ExternalLink className="w-4 h-4 mr-1" />
                    阅读原文
                  </a>
                </div>
              </div>
            </div>
          </article>
        ))}
      </div>

      {/* 加载更多 */}
      {news.length > 0 && (
        <div className="text-center pt-6">
          {hasMore ? (
            <button
              onClick={loadMore}
              disabled={loading}
              className="inline-flex items-center px-6 py-3 bg-white border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              {loading ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  加载中...
                </>
              ) : (
                '加载更多'
              )}
            </button>
          ) : (
            <p className="text-gray-500">没有更多内容了</p>
          )}
        </div>
      )}

      {/* 空状态 */}
      {news.length === 0 && !loading && (
        <div className="text-center py-12">
          <ImageIcon className="w-12 h-12 text-gray-400 mx-auto mb-4" />
          <h3 className="text-lg font-medium text-gray-900 mb-2">暂无资讯</h3>
          <p className="text-gray-600">
            {category === '全部' ? '暂无AI资讯内容' : `暂无${category}资讯`}
          </p>
        </div>
      )}
    </div>
  );
};

export default NewsList;
